public class Solution {
    // soma[m] = soma[m sem o bit mais baixo] + nums[índice desse bit]. O(2^n) no total.
    static int subconjuntosComSoma(int[] nums, long alvo) {
        int n = nums.length;
        long[] soma = new long[1 << n];
        int total = alvo == 0 ? 1 : 0; // máscara vazia
        for (int m = 1; m < 1 << n; m++) {
            int baixo = m & -m;                         // isola o bit mais baixo
            soma[m] = soma[m & (m - 1)] + nums[Integer.numberOfTrailingZeros(baixo)];
            if (soma[m] == alvo) total++;
        }
        return total;
    }

    // Kernighan: x & (x - 1) apaga o bit mais baixo; uma volta por bit ligado.
    static int popcount(int x) {
        int c = 0;
        while (x != 0) {
            x &= x - 1;
            c++;
        }
        return c;
    }
}

