import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void somas() {
        assertEquals(2, Solution.subconjuntosComSoma(new int[]{1, 2, 3}, 3));   // {3}, {1, 2}
        assertEquals(1, Solution.subconjuntosComSoma(new int[]{1, 2, 3}, 0));   // vazio
        assertEquals(0, Solution.subconjuntosComSoma(new int[]{}, 5));
    }

    @Test void vinteElementos() {
        int[] a = new int[20];
        java.util.Arrays.fill(a, 1);
        assertEquals(184_756, Solution.subconjuntosComSoma(a, 10)); // C(20, 10)
    }

    @Test void negativosEGrandes() {
        assertEquals(2, Solution.subconjuntosComSoma(new int[]{Integer.MAX_VALUE, Integer.MAX_VALUE, -1}, Integer.MAX_VALUE));
        assertEquals(1, Solution.subconjuntosComSoma(new int[]{Integer.MAX_VALUE, Integer.MAX_VALUE}, 2L * Integer.MAX_VALUE));
    }

    @Test void popcount() {
        assertEquals(0, Solution.popcount(0));
        assertEquals(3, Solution.popcount(0b1011));
        assertEquals(32, Solution.popcount(-1));
        assertEquals(1, Solution.popcount(Integer.MIN_VALUE));
        for (int x = -1000; x <= 1000; x++) assertEquals(Integer.bitCount(x), Solution.popcount(x));
    }
}
